INSERT INTO user_roles (user_id, role_id)
SELECT u.id, r.id
  FROM users u
  JOIN roles r ON r.code = 'ATTENDANCE'
 WHERE u.email = 'checkin@hosifest.test'
ON CONFLICT DO NOTHING;

-- No SOUVENIR role exists in rbac.ts. Souvenir catalog admin requires
-- config:write, which only ADMIN has, so this operator gets ADMIN rather than
-- a role that cannot perform its own job.
INSERT INTO user_roles (user_id, role_id)
SELECT u.id, r.id
  FROM users u
  JOIN roles r ON r.code = 'ADMIN'
 WHERE u.email = 'souvenir@hosifest.test'
ON CONFLICT DO NOTHING;

